exercises.starter:
import numpy as np

m, g, k = 0.1, 9.81, 1.0e4          # 100 g ball, penalty floor of stiffness 1e4 N/m (perfectly elastic)

def force(y):
    return -m * g + (k * -y if y < 0 else 0.0)

def first_apex(dt, y=1.0, v=0.0):
    """Drop the ball from y = 1 m and return the height of its first apex after bouncing."""
    rising = False
    while True:
        y, v = y + dt * v, v + dt * force(y) / m      # explicit Euler: gains energy at every contact
        if v > 0:
            rising = True
        elif rising:
            return y

exercises.tests:
for dt in (1e-3, 5e-4, 2e-4):
    a = first_apex(dt)
    assert abs(a - 1.0) < 0.01, f"with dt = {dt} the first apex should be within 1 cm of 1 m; got {a:.3f} m"

